def bob_response(hey_bob: str) -> str:
    s = hey_bob.strip()
    if not s:
        return "Fine. Be that way!"
    is_shout = s.isupper()
    is_question = s.endswith("?")
    if is_shout and is_question:
        return "Calm down, I know what I'm doing!"
    if is_shout:
        return "Whoa, chill out!"
    if is_question:
        return "Sure."
    return "Whatever."
